// The streams clause's fixture, the provider (§5.4 "Streams"): its point handler `makeTone` answers acceptance-stream-a's
// `points.stream` call with an async iterable of generated bytes (seed 3, pieces of 64 KiB), which the host runtime pumps
// into the stream a piece at a time under the daemon's back-pressure. `nosy` opens a stream to a component it hasn't (a
// stream connects only a plugin's own halves) and writes to a stream id that isn't its own; both are refused.

type Api = { streams: { open(name: string): Promise<unknown>; write(id: string, bytes: Uint8Array): Promise<void> } };
let api: Api | undefined;

export function start(a: Api): void {
  api = a;
}

/** Bytes `from`..`from + n` of the stream of `seed`: the same function in every half. */
function gen(seed: number, from: number, n: number): Uint8Array {
  const b = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const k = from + i;
    b[i] = (k * 131 + (k >>> 8) * 7 + seed * 13) & 255;
  }
  return b;
}

export async function makeTone(args: { bytes?: number } | null): Promise<AsyncIterable<Uint8Array>> {
  const bytes = typeof args?.bytes === "number" ? args.bytes : 2_000_000;
  return (async function* () {
    for (let at = 0; at < bytes; at += 65_536) yield gen(3, at, Math.min(65_536, bytes - at));
  })();
}

export async function nosy(): Promise<Record<string, unknown>> {
  if (api === undefined) throw new Error("not started");
  const said = (e: unknown) => (e instanceof Error ? e.message : String(e));
  const opened = await api.streams.open("down").then(() => "opened", said);
  const wrote = await api.streams.write("strm_00000000-0000-0000-0000-000000000000", new Uint8Array(1)).then(() => "wrote", said);
  return { opened, wrote };
}
